{
  "missing_information": [
    {
      "category": "Trigger",
      "gap": "It is unclear what event or action initiates the summarization process after the meeting ends (e.g., manual trigger by a participant, automatic recording stop, calendar event completion).",
      "why_it_matters": "The trigger determines whether the workflow can be automated end-to-end or requires a human to start it, which directly affects automation feasibility."
    },
    {
      "category": "Summary Creation Method",
      "gap": "It is not specified how the meeting summary is created — whether it is written manually by a designated person, generated from a transcript, or produced by an AI tool.",
      "why_it_matters": "The method of summary creation is the most labor-intensive step and the primary candidate for automation; knowing the current approach is essential for identifying improvement opportunities."
    },
    {
      "category": "Recipient Determination",
      "gap": "There is no information about how the list of email recipients is determined — whether it is fixed, based on meeting attendees, or decided ad hoc by the sender.",
      "why_it_matters": "Automating recipient selection requires a clear, consistent rule; ambiguity here could lead to over- or under-distribution of sensitive information."
    },
    {
      "category": "Review and Approval",
      "gap": "It is unknown whether the summary goes through any review or approval step before being sent, and if so, who is responsible for approving it.",
      "why_it_matters": "An approval step adds a decision node to the process that must be modeled and may block full automation."
    },
    {
      "category": "Email Composition",
      "gap": "The structure and required content of the email are not defined — for example, whether it includes action items, decisions, deadlines, or attachments in addition to the narrative summary.",
      "why_it_matters": "Knowing the required email content is necessary to design or automate the composition step accurately and consistently."
    },
    {
      "category": "Timing and SLA",
      "gap": "There is no indication of the expected time between the end of the meeting and the sending of the summary email.",
      "why_it_matters": "Time constraints affect process design priorities; a strict SLA may make automation more urgent and influence tool selection."
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What event or action currently starts the summarization process after a meeting ends — for example, does a specific person manually initiate it, or is it triggered automatically by a system such as a calendar or conferencing tool?",
      "targets": ["Trigger"]
    },
    {
      "id": "Q2",
      "question": "How is the meeting summary currently created — is it written manually by a participant, derived from a recorded transcript, or generated with the help of an automated or AI-based tool?",
      "targets": ["Summary Creation Method"]
    },
    {
      "id": "Q3",
      "question": "How is the list of email recipients determined — is it always the set of meeting attendees, a predefined distribution list, or does the sender decide case by case?",
      "targets": ["Recipient Determination"]
    },
    {
      "id": "Q4",
      "question": "Does the summary need to be reviewed or approved by anyone before the email is sent, and if so, who holds that responsibility?",
      "targets": ["Review and Approval"]
    },
    {
      "id": "Q5",
      "question": "What content is expected to appear in the summary email — for instance, is it a free-form narrative, or must it include structured elements such as action items, owners, and deadlines?",
      "targets": ["Email Composition"]
    },
    {
      "id": "Q6",
      "question": "Is there a target or maximum time limit within which the summary email must be sent after the meeting concludes?",
      "targets": ["Timing and SLA"]
    }
  ]
}
